def balanced(s):
    """Return True if brackets in s are balanced, ignoring quoted strings."""
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    in_string = False
    i = 0

    while i < len(s):
        ch = s[i]

        if in_string:
            if ch == '\\':
                # Skip the escaped character. If it is the final character,
                # the string is still unterminated.
                i += 2
                continue
            if ch == '"':
                in_string = False
            i += 1
            continue

        if ch == '"':
            in_string = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != matching[ch]:
